// Parse Python RAG output with improved error handling
const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';
const exitCode = $input.first().json.exitCode || 0;

// Handle errors
if (exitCode !== 0 || stderr) {
  let errorMessage = 'Sorry, I encountered an error processing your question.';

  if (stderr.includes('OPENAI_API_KEY')) {
    errorMessage = '🔑 OpenAI API key is missing. Please configure your environment variables.';
  } else if (stderr.includes('Database not found')) {
    errorMessage = '📚 Database not found. Please run create_database.py first to index your documents.';
  } else if (stderr.includes('Error -')) {
    // Extract custom error message
    const match = stderr.match(/Error - (.+)/);
    if (match) {
      errorMessage = `⚠️ ${match[1]}`;
    }
  }

  return [{
    json: {
      output: errorMessage,
      error: true,
      stderr: stderr
    }
  }];
}

// Extract Response and Sources
let response = '';
let sources = [];

const lines = stdout.split('\n');
for (const line of lines) {
  if (line.startsWith('Response:')) {
    response = line.replace('Response:', '').trim();
  } else if (line.startsWith('Sources:')) {
    try {
      const sourcesStr = line.replace('Sources:', '').trim();
      sources = JSON.parse(sourcesStr);
    } catch (e) {
      // Fallback if JSON parsing fails
      sources = [];
    }
  }
}

// Format output with sources
let output = response || 'No response generated';

if (sources.length > 0 && Array.isArray(sources)) {
  output += '\n\n📚 **Sources:**\n';
  sources.forEach((src, idx) => {
    const fileName = src.file ? src.file.split('/').pop() : 'Unknown';
    const confidence = src.score ? ` (confidence: ${(src.score * 100).toFixed(0)}%)` : '';
    output += `${idx + 1}. ${fileName}${confidence}\n`;
  });
}

return [{
  json: {
    output: output,
    raw_response: response,
    sources: sources,
    error: false
  }
}];
